export interface EditorConfig {
  placeholder?: string;
  disabled?: boolean;
  height?: string;
  maxHeight?: string;
  showToolbar?: boolean;
  enabledTools?: string[];
  toolbarConfig?: ToolbarConfig;
  validation?: ValidationConfig;
  theme?: ThemeConfig;
  fullScreen?: FullScreenConfig;
  table?: TableConfig;
}

export interface EditorState {
  bold: boolean;
  italic: boolean;
  underline: boolean;
  strikethrough: boolean;
  subscript: boolean;
  superscript: boolean;
  fontSize: string;
  fontFamily: string;
  textColor: string;
  alignment: string;
  heading: string;
  listType: string;
}

export interface LinkData {
  url: string;
  text: string;
  target: '_blank' | '_self' | '_parent' | '_top';
  title?: string;
}

export interface MediaEmbedData {
  type: 'youtube' | 'twitter' | 'instagram' | 'vimeo' | 'custom';
  url: string;
  embedCode?: string;
  width?: string;
  height?: string;
  previewUrl?: string;
  title?: string;
}

export interface LinkPreview {
  url: string;
  title?: string;
  description?: string;
  image?: string;
  domain?: string;
}

export interface TableData {
  rows: number;
  columns: number;
  cells: TableCell[][];
  style?: {
    width?: string;
    height?: string;
    borderCollapse?: string;
    border?: string;
  };
}

export interface TableCell {
  content: string;
  style?: CellStyle;
  colspan?: number;
  rowspan?: number;
  isHeader?: boolean;
}

export interface TableStyle {
  width?: string;
  height?: string;
  borderCollapse?: string;
  border?: string;
  backgroundColor?: string;
  margin?: string;
}

export interface CellStyle {
  padding?: string;
  border?: string;
  backgroundColor?: string;
  textAlign?: string;
  verticalAlign?: string;
  fontWeight?: string;
  color?: string;
  width?: string;
  height?: string;
}

export interface WordCountStats {
  words: number;
  characters: number;
  charactersNoSpaces: number;
  paragraphs: number;
  sentences: number;
  readingTime: number;
}

export interface SpellCheckSuggestion {
  word: string;
  suggestions: string[];
  position: { start: number; end: number };
  startOffset: number;
  endOffset?: number;
  description?: string;
  type?: string;
}

export interface ValidationConfig {
  showWordCount?: boolean;
  showCharacterCount?: boolean;
  showReadingTime?: boolean;
  maxWords?: number;
  maxCharacters?: number;
  minWords?: number;
  minCharacters?: number;
  spellCheck?: {
    enabled?: boolean;
    language?: string;
    highlightErrors?: boolean;
    showSuggestions?: boolean;
    ignoredWords?: string[];
    customDictionary?: string[];
  };
}

export interface ThemeConfig {
  mode?: 'light' | 'dark' | 'auto';
  primaryColor?: string;
  secondaryColor?: string;
  backgroundColor?: string;
  textColor?: string;
  borderColor?: string;
  customCss?: string;
}

export interface FullScreenConfig {
  enabled?: boolean;
  hideToolbarInFullScreen?: boolean;
  exitOnEscape?: boolean;
  distractionFree?: boolean;
}

export interface TableConfig {
  enabled?: boolean;
  defaultRows?: number;
  defaultColumns?: number;
  maxRows?: number;
  maxColumns?: number;
  resizable?: boolean;
  sortable?: boolean;
  allowAddDelete?: boolean;
  allowResize?: boolean;
  cellPadding?: string;
  borderWidth?: string;
  borderColor?: string;
  headerBackgroundColor?: string;
  alternateRowColor?: boolean;
  showBorders?: boolean;
  showGridLines?: boolean;
  cellMinWidth?: string;
  cellMinHeight?: string;
  allowMerge?: boolean;
  allowSplit?: boolean;
  tableClasses?: string[];
}

